"""Original demonstration content and reusable owner-editable post formats."""
from html import escape
from pathlib import Path
import json

def checklist(items, class_name=''):
    return '<ul class="cl-checklist '+class_name+'">'+''.join('<li><label><input type="checkbox"/><span>'+escape(x)+'</span></label></li>' for x in items)+'</ul>'

def table(headers, rows):
    return '<table><thead><tr>'+''.join('<th scope="col">'+escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<th scope="row">'+escape(x)+'</th>' if i==0 else '<td>'+escape(x)+'</td>' for i,x in enumerate(row))+'</tr>' for row in rows)+'</tbody></table>'

def facts(items):
    return '<dl class="cl-facts">'+''.join('<div><dt>'+escape(k)+'</dt><dd>'+escape(v)+'</dd></div>' for k,v in items)+'</dl>'

def feature(c, post):
    title=escape(post['title']);i=post['index']-1;kind=c['feature']
    actions='<div class="cl-actions"><button type="button" data-print="true" hidden>Print this page</button><button type="button" data-reset-checklist="true" hidden>Reset checklist</button></div>'
    if kind=='recipe':
        data=json.loads((Path(__file__).parent/'recipes.json').read_text())[i]
        times=' data-prep-time="'+data['prep']+'"'+(' data-cook-time="'+data['cook']+'"' if data['cook'] else '')
        notes='Refrigerate overnight' if i==6 else 'Season to taste'
        return '<section class="cl-feature-box" id="recipe" data-recipe="true"'+times+'><p class="cl-kicker">The recipe card</p><h2 class="recipe-name">'+title+'</h2>'+facts([('Preparation',data['prep'].removeprefix('PT').removesuffix('M')+' minutes'),('Yield',data['yield_text']),('Notes',notes)])+'<p class="recipe-yield">'+data['yield_text']+'</p><h3>Ingredients</h3>'+checklist(data['ingredients'],'recipe-ingredients')+'<h3>Method</h3><ol class="recipe-instructions">'+''.join('<li>'+escape(step)+'</li>' for step in data['instructions'])+'</ol>'+actions+'</section>'
    if kind=='itinerary':
        place=['Lisbon','Lisbon','Kyoto','Kyoto','Copenhagen','Copenhagen'][i] if i<6 else 'Your next destination'
        return '<section class="cl-feature-box" id="practical-notes"><p class="cl-kicker">The practical notes</p><h2>A day in '+escape(place)+'</h2>'+facts([('Pace','Unhurried'),('Getting around','Walk & public transport'),('Planning','Leave room to adjust')])+table(['Part of the day','A starting point','Leave room for'],[['Morning','Choose one neighbourhood','A coffee stop and a useful detour'],['Afternoon','Visit one place you have researched','Opening times and the weather'],['Evening','Return by a different route','A quiet meal near where you stay']])+'<p>Check current opening times and transport details with the destination’s official services before making a plan.</p>'+actions+'</section>'
    if kind=='lesson':
        path='HTML foundations' if i<6 else 'CSS layout';step=i%6+1
        example='&lt;main&gt;\n  &lt;h1&gt;One clear idea&lt;/h1&gt;\n  &lt;p&gt;Explain it in a useful order.&lt;/p&gt;\n&lt;/main&gt;' if i<6 else '.reading-layout {\n  display: grid;\n  grid-template-columns: minmax(0, 44rem);\n  justify-content: center;\n  gap: 1.5rem;\n}'
        return '<section class="cl-feature-box" id="lesson-outline"><p class="cl-kicker">'+path+' · Lesson '+str(step)+' of 6</p><h2>What you will practise</h2>'+facts([('Path',path),('Approach','Read → try → review'),('Resources','On this page')])+checklist(['Read the explanation before copying the example.','Change one part and describe what happened.','Use the keyboard to review the result.'])+'<h3>A small example</h3><pre><code>'+example+'</code></pre><details><summary>Show a reflection prompt</summary><p>Explain the example to a person who has not seen the code. Which part does the most useful work?</p></details></section>'
    if kind=='review':
        return '<aside class="cl-disclosure">Demonstration review format. Products and test results in this sample are illustrative; replace them with your own observations and affiliate disclosure.</aside><section class="cl-feature-box" id="review-notes"><p class="cl-kicker">At a glance</p><h2>The details worth comparing</h2>'+table(['Criterion','What to record','Evidence'],[['Everyday use','The tasks you actually tried','Your own notes and photographs'],['Fit and finish','The materials and controls','What you can directly observe'],['Compatibility','The devices and standards checked','Manufacturer details, with a date'],['Ownership','Repair, support and replaceable parts','Sources and limitations']])+'<div class="cl-split-note"><div><h3>What worked well</h3><p>Describe a specific benefit you observed, including who it is useful for.</p></div><div><h3>What to consider</h3><p>Explain the trade-off and the limits of your testing rather than inventing a score.</p></div></div></section>'
    if kind=='project':return '<section class="cl-feature-box" id="project"><p class="cl-kicker">Project planner</p><h2>Before you begin</h2>'+facts([('Format','Weekend project'),('Plan','Measure & sketch'),('Method','Owner-supplied')])+checklist(['Record your measurements.','List the materials and tools for your own plan.','Check the product instructions and workspace requirements.','Photograph the starting point.'])+'<details><summary>Open the project reflection</summary><p>What changed between your first sketch and the final result? Keep a short record beside the finished photograph.</p></details>'+actions+'</section>'
    if kind=='lookbook':return '<section class="cl-feature-box" id="credits"><p class="cl-kicker">The details</p><h2>Credits & context</h2>'+table(['Piece','Why it is here','Credit'],[['The foundation','Describe the shape, texture or purpose','Add the actual maker and product'],['The useful extra','Explain how it changes the look','Add a source or second-hand note'],['The finishing detail','Keep the description specific','Credit the photographer or stylist']])+'<p>Use clearly labeled external product links and disclose any affiliate relationship. This template does not add a shop or checkout.</p></section>'
    if kind in ['checklist','care']:return '<section class="cl-feature-box" id="useful-list"><p class="cl-kicker">Keep it practical</p><h2>A checklist to make your own</h2>'+checklist(['Write down the routine or plan in your own words.','Add the information another person would need.','Keep contact details and private records somewhere appropriate.','Review the list when circumstances change.'])+actions+'</section>'
    if kind=='book':return '<section class="cl-feature-box" id="book-notes"><p class="cl-kicker">The reading card</p><h2>A place for the book’s details</h2>'+facts([('Author','Add the real author'),('Edition','Record the edition'),('Reading notes','Personal observations')])+'<blockquote>A useful review explains what stayed with the reader, and why.</blockquote><h3>Questions for a second reading</h3><ol><li>Which passage changed the way you understood the book?</li><li>Who would you recommend this edition to?</li><li>What would you like to ask the author?</li></ol></section>'
    if kind=='game':return '<section class="cl-feature-box" id="game-notes"><p class="cl-kicker">Review notebook</p><h2>Describe the experience</h2>'+facts([('Platform','Tested platform'),('Version','Version & date'),('Scope','Time played')])+table(['Area','What to document'],[['Controls','Remapping, input options and what you tried'],['Access','Settings and barriers you observed'],['Performance','Device, configuration and limitations'],['Experience','The part you can discuss without spoilers']])+'<details><summary>Open the spoiler discussion</summary><p>Keep story-specific observations inside this clearly labeled section.</p></details></section>'
    if kind=='episode':return '<section class="cl-feature-box" id="episode-notes"><p class="cl-kicker">Episode notebook</p><h2>Listen, then keep exploring</h2><p>Add a player from your actual podcast or video host. This demo intentionally loads no third-party media or tracking.</p>'+facts([('Format','Conversation'),('Notes','Transcript below'),('Subscribe','Use your actual feed')])+'<h3>Chapters</h3><ol><li>Opening question</li><li>The useful example</li><li>What we learned</li></ol><details><summary>Read the demonstration transcript</summary><p><strong>Host:</strong> What helped you begin?</p><p><strong>Guest:</strong> We chose one small question and gave ourselves enough time to answer it clearly.</p></details></section>'
    if kind=='plant':return '<section class="cl-feature-box" id="plant-notes"><p class="cl-kicker">Plant notebook</p><h2>Observe before you generalise</h2>'+facts([('Location','Your actual growing space'),('Season','Date your observations'),('Conditions','Record what you measured')])+checklist(['Add a clear plant identification and source.','Describe the light and growing conditions.','Record changes with dated photographs.','Keep your own observations separate from general care advice.'])+actions+'</section>'
    if kind=='routine':return '<section class="cl-feature-box" id="routine"><p class="cl-kicker">Personal journal format</p><h2>A flexible session record</h2>'+table(['Part','Your plan','Your reflection'],[['Start','What do you have time and space for?','How did you feel about starting?'],['Session','Record your own activity and adjustments','What felt useful?'],['Finish','Leave a note for next time','What would you change?']])+'<p>This is a publishing and reflection format. Authors supply any actual instruction and the relevant professional context.</p>'+actions+'</section>'
    if kind=='budget':return '<section class="cl-feature-box" id="budget-example"><p class="cl-kicker">A local arithmetic example</p><h2>Income minus expenses</h2><div class="cl-budget" data-budget="true" role="group" aria-label="Example budget calculator"><label>Example monthly income <input name="income" type="number" min="0" step="0.01" value="2500" required/></label><label>Example monthly expenses <input name="expenses" type="number" min="0" step="0.01" value="1800" required/></label><button type="button" data-budget-calculate="true">Calculate difference</button><output aria-live="polite">Income minus expenses: 700.00</output><noscript><p>JavaScript is needed to update this arithmetic example. The example values shown are 2,500 minus 1,800.</p></noscript></div><p class="cl-small">This example runs in your browser. Values are not saved or sent anywhere. State the currency and assumptions when publishing your own example.</p></section>'
    if kind=='spoiler':return '<section class="cl-feature-box" id="viewing-notes"><p class="cl-kicker">The viewing notebook</p><h2>Before the spoilers</h2>'+facts([('Format','Review or recap'),('Viewed','Edition & date'),('Credits','Add actual credits')])+'<p>Use the opening section to describe the tone, craft and intended audience without revealing major story details.</p><details><summary>Continue to the spoiler discussion</summary><p>Place plot-specific observations here. Readers choose whether to open this section, and no script is required.</p></details></section>'
    if kind=='event':return '<section class="cl-feature-box" id="event-details"><p class="cl-kicker">Illustrative community listing</p><h2>An open afternoon</h2>'+facts([('When','Example: 12 December 2026'),('Where','Add the actual venue'),('Access','Describe access information')])+'<p>Replace this example with a real organiser, current date, address and cancellation details. Link to the organiser’s own RSVP page when one is available.</p><h3>Questions to answer</h3>'+checklist(['Who is organising the event?','Is registration required?','What access and travel information is available?','Where can visitors check for updates?'])+'</section>'
    if kind=='case-study':return '<section class="cl-feature-box" id="project-context"><p class="cl-kicker">Demonstration case study</p><h2>The brief behind the work</h2>'+facts([('Role','Describe your actual role'),('Scope','Name the deliverables'),('Context','Credit the collaborators')])+'<div class="cl-split-note"><div><h3>The question</h3><p>Describe the original problem, the audience and the constraints.</p></div><div><h3>The decision</h3><p>Show the choices you made and the evidence behind them.</p></div></div><p>Only publish outcomes, metrics and testimonials you can substantiate. The sample project is fictional.</p></section>'
    if kind=='release':return '<section class="cl-feature-box" id="release-note"><p class="cl-kicker">A useful release note</p><h2>What changed, and who it helps</h2>'+table(['Area','Before','After'],[['Trigger','Describe the old behaviour','Describe the new behaviour'],['User impact','Name the affected task','Explain the resulting benefit'],['Getting started','List any old setup','Explain the actual upgrade step']])+'<h3>Migration checklist</h3>'+checklist(['Link to the real release or product documentation.','Explain whether an action is required.','Record known limitations and support options.'])+'</section>'
    if kind=='event-story':return '<section class="cl-feature-box" id="event-credits"><p class="cl-kicker">An illustrative event story</p><h2>The people behind the details</h2>'+table(['Contribution','Credit to add'],[['Planning','Actual planner or organising team'],['Photography','Actual photographer and usage permission'],['Venue','Venue name and location'],['Details','Designers, makers and other collaborators']])+'<p>Publish real-event stories with the relevant permissions. Use your own inquiry destination; this theme does not supply booking or payment processing.</p></section>'
    return '<section class="cl-feature-box" id="impact-note"><p class="cl-kicker">Demonstration impact report</p><h2>Show the work in context</h2>'+table(['Question','What to publish'],[['What happened?','A dated account of the actual activity'],['Who took part?','Participants and consent-aware credits'],['What changed?','Evidence, methodology and limitations'],['What happens next?','A clear next step and responsible contact']])+'<p>Use real, sourced figures and genuine organisation details. Donation and volunteer registration links must point to your chosen external service.</p></section>'

def body(c,post,image_url):
    title=escape(post['title']);feature_html=feature(c,post)
    first=c['slug'] in ['saffron','wayfarer','lesson','bench']
    intros={
      'saffron':'A recipe page should feel useful before it feels busy. This demonstration pairs a simple kitchen story with an editable recipe card, readable ingredients and a print-friendly method. Replace the sample method with a recipe you have cooked and tested.',
      'wayfarer':'Start with one place and a few things you want to notice. This guide demonstrates a slower way to arrange a destination story: a clear opening, practical notes, an itinerary you can adjust, and enough context to plan your own visit.',
      'lesson':'Start with one clear idea. This lesson demonstrates how to arrange an explanation, a small example and a practical exercise so a reader can move from understanding the words to trying the work. Use the sequence links in your own learning-path index.',
      'bench':'A useful review makes its method visible. This demonstration separates what was observed, how it was checked and which trade-offs matter. The example is a publishing format, not a product test or an endorsement.',
    }
    intro=intros.get(c['slug'],'This original demonstration article explores “'+post['title']+'” using the '+c['name']+' post format. The sample shows how to combine a readable story, useful context and a practical reference section. Replace the illustrative details with your own reporting and images before using it as a real publication.')
    sections={
      'saffron':[('A note from the kitchen','The best recipe notes explain the choices that matter: how an ingredient is prepared, what can be made ahead, and which finishing details change the dish. Keep the story close to those useful observations.'),('Make the page your own','Add your tested quantities and instructions in the recipe card. Use a photograph or original illustration of the dish, include any optional serving notes, and check the print preview before publishing.'),('Keep a useful record','After cooking, write down the adjustments you would repeat. A short, specific note is more useful than an unsupported claim that a recipe always works for everyone.')],
      'wayfarer':[('Start with a neighbourhood','Choose a manageable area and give the reader a reason to start there. Explain what is close together, where the route changes character, and which details you observed yourself.'),('Leave room between the plans','An itinerary is a starting point rather than a promise. Keep time-sensitive details dated, link to official opening and transport information, and include an alternative for a wet afternoon.'),('Bring the story home','A useful destination guide leaves readers with a sense of the place and a practical next step. Finish with one recommendation about how to plan, rather than an impossible list of everything to see.')],
      'lesson':[('The idea in plain language','Name the task before showing the code. Explain what the reader should be able to do at the end, and keep the first example small enough to understand without switching between several tools.'),('Try one change','Copy the small example, then alter one part. Describe the difference you observe. If the result is unexpected, return to the smallest working version and compare the change carefully.'),('Review what you made','Read the result without its decoration and navigate it with the keyboard. A clear structure and a useful explanation should survive when the optional enhancements are unavailable.')],
      'bench':[('Begin with the actual task','State who the product is for and which tasks were checked. Record the version, device or setting that affects the result. Avoid turning manufacturer claims into first-hand observations.'),('Separate facts from judgement','Specification tables should identify their source and date. Opinions should explain the evidence behind them. A comparison becomes useful when the reader can understand both the benefit and the compromise.'),('Explain the limits','End with the circumstances in which the product makes sense and the questions your review does not answer. Update the record when new evidence changes a conclusion.')],
    }.get(c['slug'],[('Begin with the context','Explain who this story is for and the question it answers. Include the details a new reader needs, and distinguish your own observations from material supplied by another source.'),('Make the useful part easy to find','The reference section below is deliberately structured for scanning, keyboard use and printing. Edit the labels and details to fit the real story rather than retaining irrelevant example fields.'),('Leave the reader with a next step','Link to a relevant topic, a dated source or a related story. Give collaborators proper credit and keep private or unverified information out of a public demonstration.')])
    jump='<p><a class="cl-button" href="#recipe">Jump to recipe</a></p>' if c['slug']=='saffron' else ''
    picture='<figure><img src="'+escape(image_url,quote=True)+'" alt="Original '+escape(c['audience'].lower(),quote=True)+' illustration for '+title+'" width="1200" height="900"/><figcaption class="cl-small">Original Colorlib illustration · demonstration content</figcaption></figure>'
    result='<p>'+escape(intro)+'</p>'+jump+picture
    for index,(heading,text) in enumerate(sections):
        result+='<h2>'+escape(heading)+'</h2><p>'+escape(text)+'</p>'
        if index==0:result+=feature_html
    return result
